import React, { useState } from "react";
import { Slider } from "primereact/slider";
import { SelectButton } from "primereact/selectbutton";

export default function Filter() {
    const [value, setValue] = useState(null);
    const [filter, setFilter] = useState('brightness');
    const [filterValues, setFilterValues] = useState({
        brightness: 100,
        contrast: 100,
        saturation: 100
    });

    const filterOptions = [
        { label: 'Brightness', value: 'brightness' },
        { label: 'Contrast', value: 'contrast' },
        { label: 'Saturation', value: 'saturation' }
    ];

    const filterStyle = () => {
        return {
            filter: `brightness(${filterValues.brightness}%) contrast(${filterValues.contrast}%) saturate(${filterValues.saturation}%)`
        }
    };

    return (
        <div className="fxb fvc">
            <div className="fxb fcol gp4">
                <img alt="user header" className="w300 border-round" src="https://primefaces.org/cdn/primevue/images/card-vue.jpg" style={filterStyle()} />
                <SelectButton value={filter} onChange={(e) => setFilter(e.value)} options={filterOptions} className="mgb3 stretch" />
                <Slider
                    value={filterValues[filter]}
                    onChange={(e) => {
                        setFilterValues(prev => ({
                            ...prev,
                            [filter]: e.value
                        }));
                    }}
                    className="w300"
                    min={0}
                    max={200}
                />
            </div>
        </div>
    )
}